using namespace ZZdlabels_mod;

//--- This is called from within the coefficient-computing routines;
//--- captures m^0, m^2 and m^4 parts of the coefficient and stores
//--- in the ggZZ_mod res array.
//
// res is NOT taken from ggZZ_mod.hpp here. The Fortran ggZZ_mod builds its own
// `res` with `allocate` plus a one-shot copy out of the C++ storage (unlike
// sprods_com_mod, which is a true c_f_pointer alias), so the two sides are
// separate allocations. The Fortran readers of `res` see only the Fortran copy,
// so ggZZcapture_fi.F90 passes that array in explicitly and we write it here.

// Fortran parameter(imt0=1,imt2=2,imt4=3) / parameter(ipp=1,imp=2)
static const int imt0 = 1;
static const int imt2 = 2;
static const int imt4 = 3;
static const int ipp = 1;
static const int imp = 2;

void ggZZcapture(const std::string& labelPadded, int labelLen, int h34, int h56,
                 int j1, int j2, int j3, int j4, int j5, int j6,
                 std::complex<double>& amp0, std::complex<double>& amp2,
                 std::complex<double>& amp4,
                 FArray4D<std::complex<double>>& res) {

  // trim(label): the declared-length prefix with trailing blanks removed.
  int n = std::min<int>(labelLen, static_cast<int>(labelPadded.size()));
  while (n > 0 && labelPadded[n-1] == ' ') --n;
  const std::string label = labelPadded.substr(0, n);

  // label(1:5) / label(6:6) read the blank-padded buffer, so a label shorter
  // than six characters compares against blanks instead of running off the end.
  auto label_1_5 = [&labelPadded]() { return labelPadded.substr(0, 5); };
  auto label_6 = [&labelPadded]() { return labelPadded[5]; };

