        for (int j = 1; j <= 4; ++j)
          for (int i = 1; i <= 2; ++i)
            res(i,j,k,l) = czip;
    first_mod::first = false;
  }

  int htag = -1;
  int ltag = 0;
  int itag = 0;

  //--- Canonical permutation:  1 2 3 4 5 6
  if ((j1 == 1) && (j2 == 2) && (j3 == 3) && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
    if ((label == "1x2") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_2;
    }
    if ((label == "1x2pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c1_2;
    }
    if ((label == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_34;
    }
    if ((label == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c1_34;
    }
    if ((label == "12x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
