      itag = c12_34;
    }
    if ((label == "12x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c12_34;
    }
    if ((label == "1x34x2mp") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d1_34_2;
    }
    if ((label == "1x34x2pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d1_34_2;
    }
    if ((label == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
