      htag = imp;
      ltag = 4;
      itag = d6_2_1_34;
    }
    if ((label_1_5() == "bubmp") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 2;
      itag = static_cast<int>(label_6()) - static_cast<int>('0');
    }
    if ((label_1_5() == "bubpp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 2;
      itag = static_cast<int>(label_6()) - static_cast<int>('0');
    }
  }

  //--- Permute 1 and 2:  2 1 3 4 5 6
  if ((j1 == 2) && (j2 == 1) && (j3 == 3) && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
