    }
  }

  //--- Permute 3,4 and 5,6:  1 2 5 6 3 4
  if ((j1 == 1) && (j2 == 2) && (j3 == 5) && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
    if ((label == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_56;
    }
