#include "w2jetsq.hpp"

#include <complex>
#include <FArray.hpp>
#include <constants_mod.hpp>
#include <mxpart_mod.hpp>
#include <lc_mod.hpp>
#include <mmsq_cs_mod.hpp>

#include "subqcd.hpp"

using namespace constants_mod;
using namespace mxpart_mod;
using namespace lc_mod;
using namespace mmsq_cs_mod;

void w2jetsq(int i1, int i2, int i3, int i4, int i5, int i6,
             FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb,
             double& msq) {

  // qcd1(-1:1,-1:1), qcd2(-1:1,-1:1), qed(-1:1,-1:1)
  FArray2D<std::complex<double>> qcd1(3, 3, -1, -1);
  FArray2D<std::complex<double>> qcd2(3, 3, -1, -1);
  FArray2D<std::complex<double>> qed(3, 3, -1, -1);

  subqcd(i1,i2,i3,i4,i5,i6,za,zb,qcd1);
  subqcd(i1,i2,i3,i4,i6,i5,za,zb,qcd2);

  qed(+1,+1) = qcd1(+1,+1) + qcd2(+1,+1);
  qed(+1,-1) = qcd1(+1,-1) + qcd2(-1,+1);
  qed(-1,+1) = qcd1(-1,+1) + qcd2(+1,-1);
  qed(-1,-1) = qcd1(-1,-1) + qcd2(-1,-1);

  double msq1 = std::norm(qcd1(+1,+1)) + std::norm(qcd1(+1,-1))
              + std::norm(qcd1(-1,+1)) + std::norm(qcd1(-1,-1));

  double msq2 = std::norm(qcd2(+1,+1)) + std::norm(qcd2(+1,-1))
              + std::norm(qcd2(-1,+1)) + std::norm(qcd2(-1,-1));

  double msqq = std::norm(qed(+1,+1)) + std::norm(qed(+1,-1))
              + std::norm(qed(-1,+1)) + std::norm(qed(-1,-1));

  mmsq_cs(0,+1,+1) = 0.0;
  mmsq_cs(1,+1,+1) = 0.0;
  mmsq_cs(2,+1,+1) = 0.0;

  if ((colourchoice == 1) || (colourchoice == 0)) {
    mmsq_cs(1,+1,+1) = msq1;
    mmsq_cs(2,+1,+1) = msq2;
  }
  if ((colourchoice == 2) || (colourchoice == 0)) {
    mmsq_cs(0,+1,+1) = -ninth*msqq;
  }

  msq = mmsq_cs(0,+1,+1) + mmsq_cs(1,+1,+1) + mmsq_cs(2,+1,+1);
}

extern "C" {
  void w2jetsq_wrapper(int i1, int i2, int i3, int i4, int i5, int i6,
                       std::complex<double>* fza, std::complex<double>* fzb,
                       double* msq) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    w2jetsq(i1,i2,i3,i4,i5,i6,za,zb,*msq);
  }
}
